use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn report_k_theory_analysis (analysis : & KTheoryAnalysis) { println ! ("\n🎯 K-Theory Dependency Analysis Results:") ; println ! ("═══════════════════════════════════════") ; for level in & analysis . levels { let essential_marker = if level . is_essential { "🔥" } else { "  " } ; println ! ("{}K{}: {} nodes, max_depth={}, avg_depth={:.1}, complexity={:.1}, critical={}" , essential_marker , level . k , level . node_count , level . max_depth , level . avg_depth , level . avg_complexity , level . critical_nodes . len ()) ; } let essential_levels : Vec < _ > = analysis . levels . iter () . filter (| level | level . is_essential) . collect () ; println ! ("\n🔥 Essential K-Levels: {}" , essential_levels . len ()) ; for level in essential_levels { println ! ("   K{}: {} critical nodes, depth {}" , level . k , level . critical_nodes . len () , level . max_depth) ; } let total_nodes : usize = analysis . levels . iter () . map (| l | l . node_count) . sum () ; let essential_nodes : usize = analysis . levels . iter () . filter (| l | l . is_essential) . map (| l | l . node_count) . sum () ; let reduction_potential = if total_nodes > 0 { (1.0 - essential_nodes as f64 / total_nodes as f64) * 100.0 } else { 0.0 } ; println ! ("\n📊 Dependency Optimization:") ; println ! ("   Total nodes: {}" , total_nodes) ; println ! ("   Essential nodes: {}" , essential_nodes) ; println ! ("   Reduction potential: {:.1}%" , reduction_potential) ; let optimal_k = analysis . levels . iter () . filter (| l | l . is_essential) . max_by_key (| l | l . critical_nodes . len ()) . map (| l | l . k) . unwrap_or (3) ; println ! ("   🎯 Recommended max K-level: K{}" , optimal_k) ; }